164	static int sf32lb52_tfcard_mount(void)
165	{
166	#ifndef CONFIG_DISABLE_MOUNTPOINT
167	  static const char *const devpaths[] =
168	  {
169	    "/dev/mmcsd0p0",
170	    "/dev/mmcsd0"
171	  };
172	  int tmpret;
173	  int ret = -ENODEV;
174	  size_t i;
175	
176	  tmpret = mkdir(SF32LB52_TFCARD_MOUNTPOINT, 0755);
177	  if (tmpret < 0 && errno != EEXIST)
178	    {
179	      serr("WARN: mkdir %s failed: %d\n", SF32LB52_TFCARD_MOUNTPOINT, errno);
180	      return -errno;
181	    }
182	
183	  for (i = 0; i < sizeof(devpaths) / sizeof(devpaths[0]); i++)
184	    {
185	      ret = nx_mount(devpaths[i], SF32LB52_TFCARD_MOUNTPOINT, "vfat", 0, NULL);
186	      if (ret >= 0 || ret == -EBUSY)
187	        {
188	          syslog(LOG_INFO, "INFO: TF mounted from %s to %s\n",
189	                 devpaths[i], SF32LB52_TFCARD_MOUNTPOINT);
190	          return OK;
191	        }
192	    }
193	
194	  return ret;
195	#else
196	  return -ENOSYS;
197	#endif
198	}
