200	static int sf32lb52_tfcard_initialize(void)
201	{
202	  FAR struct spi_dev_s *spi;
203	  int ret;
204	
205	  spi = sf32lb52_spi1_getbus();
206	  if (spi == NULL)
207	    {
208	      serr("ERROR: sifli_spibus_initialize(%d) failed\n",
209	           SF32LB52_TFCARD_SPI_PORT);
210	      return -ENODEV;
211	    }
212	
213	  ret = mmcsd_spislotinitialize(SF32LB52_TFCARD_MINOR,
214	                                SF32LB52_TFCARD_SLOT,
215	                                spi);
216	  if (ret < 0)
217	    {
218	      serr("ERROR: mmcsd_spislotinitialize failed: %d\n", ret);
219	      return ret;
220	    }
221	
222	  ret = sf32lb52_tfcard_mount();
223	  if (ret < 0)
224	    {
225	      serr("WARN: TF mount failed: %d\n", ret);
226	    }
227	
228	  return ret;
229	}
