233	#if defined(CONFIG_I2C) && defined(CONFIG_SENSORS_LSM6DSL)
234	static int sf32lb52_lsm6ds3_initialize(FAR struct i2c_master_s *i2c)
235	{
236	  int ret;
237	
238	  /* LSM6DS3TR-C is register-compatible enough with the in-tree LSM6DSL
239	   * test driver for board bringup.  The board wiring is:
240	   *   PA39 - I2C2 SDA
241	   *   PA40 - I2C2 SCL
242	   *   PA31 - INT
243	   *   PA30 - sensor LDO enable, active high
244	   */
245	
246	  HAL_PIN_Set(PAD_PA30, GPIO_A30, PIN_NOPULL, 1);
247	  sifli_gpio_config(SF32LB52_LSM6DS3_LDO_PIN, GPIO_OUTPUT);
248	  sifli_gpio_write(SF32LB52_LSM6DS3_LDO_PIN, true);
249	  usleep(10000);
250	
251	  HAL_PIN_Set(PAD_PA31, GPIO_A31, PIN_PULLUP, 1);
252	  sifli_gpio_config(SF32LB52_LSM6DS3_INT_PIN, GPIO_INPUT);
253	
254	  ret = lsm6dsl_sensor_register(SF32LB52_LSM6DS3_DEVPATH,
255	                                i2c,
256	                                LSM6DSLACCEL_ADDR0);
257	  if (ret < 0)
258	    {
259	      syslog(LOG_WARNING,
260	             "WARN: LSM6DS3 not found at 0x%02x on I2C%d: %d\n",
261	             LSM6DSLACCEL_ADDR0, SF32LB52_LSM6DS3_I2C_BUS, ret);
262	
263	      ret = lsm6dsl_sensor_register(SF32LB52_LSM6DS3_DEVPATH,
264	                                    i2c,
265	                                    LSM6DSLACCEL_ADDR1);
266	    }
267	
268	  if (ret < 0)
269	    {
270	      syslog(LOG_ERR,
271	             "ERROR: LSM6DS3 register failed on I2C%d: %d\n",
272	             SF32LB52_LSM6DS3_I2C_BUS, ret);
273	      return ret;
274	    }
275	
276	  syslog(LOG_INFO,
277	         "INFO: LSM6DS3 test device registered as %s, INT=%d\n",
278	         SF32LB52_LSM6DS3_DEVPATH, SF32LB52_LSM6DS3_INT_PIN);
279	  return OK;
280	}
281	#endif
