323	/****************************************************************************
324	 * Name: sf32lb52_lchspi_ulp_bringup
325	 *
326	 * Description:
327	 *   Perform architecture-specific initialization
328	 *
329	 *   CONFIG_BOARD_LATE_INITIALIZE=y
330	 *     Called from board_late_initialize().
331	 *
332	 *   CONFIG_BOARD_LATE_INITIALIZE=n && CONFIG_BOARDCTL=y
333	 *     Called from the NSH library
334	 *
335	 ****************************************************************************/
336	
337	int sf32lb52_lchspi_ulp_bringup(void)
338	{
339	  int ret = OK;
340	  int tmpret;
341	
342	#ifdef CONFIG_FS_PROCFS
343	  tmpret = mkdir("/proc", 0755);
344	  if (tmpret < 0 && errno != EEXIST)
345	    {
346	      serr("WARN: mkdir /proc failed: %d\n", errno);
347	    }
348	
349	  tmpret = nx_mount(NULL, "/proc", "procfs", 0, NULL);
350	  if (tmpret < 0 && tmpret != -EBUSY)
351	    {
352	      serr("WARN: mount procfs failed: %d\n", tmpret);
353	    }
354	#endif
355	
356	  tmpret = mkdir("/data", 0755);
357	  if (tmpret < 0 && errno != EEXIST)
358	    {
359	      serr("WARN: mkdir /data failed: %d\n", errno);
360	    }
361	
362	#ifdef CONFIG_FS_TMPFS
363	  /* Keep /data writable for syscall and file API test cases. */
364	  tmpret = nx_mount(NULL, "/data", "tmpfs", 0, NULL);
365	  if (tmpret < 0 && tmpret != -EBUSY)
366	    {
367	      serr("WARN: mount tmpfs on /data failed: %d\n", tmpret);
368	    }
369	#endif
370	
371	#if defined(CONFIG_RTC) && defined(CONFIG_RTC_DRIVER)
372	  struct rtc_lowerhalf_s *rtclower = NULL;
373	
374	  rtclower = sf32lb_rtc_lowerhalf();
375	  if (rtclower == NULL)
376	    {
377	      serr("ERROR: Failed to instantiate RTC lower-half\n");
378	      return -ENOMEM;
379	    }
380	
381	  ret = rtc_initialize(0, rtclower);
382	  if (ret < 0)
383	    {
384	      serr("ERROR: rtc_initialize failed: %d\n", ret);
385	      return ret;
386	    }
387	#endif
388	
389	#ifdef CONFIG_ADC
390	  ret = sf32lb_adc_init("/dev/adc0");
391	  if (ret < 0)
392	    {
393	      serr("ERROR: sf32lb_adc_init failed: %d\n", ret);
394	      return ret;
395	    }
396	#endif
397	
398	#ifdef CONFIG_DEV_GPIO
399	  ret = sifli_gpio_initialize();
400	  if (ret < 0)
401	    {
402	      syslog(LOG_ERR, "ERROR: sifli_gpio_initialize failed: %d\n", ret);
403	      return ret;
404	    }
405	#endif
406	
407	#ifdef CONFIG_TIMER
408	#if SF32LB_TIMER_DEFAULT_INDEX >= 0
409	  {
410	    FAR struct timer_lowerhalf_s *timer_lower;
411	    FAR void *timer_upper;
412	
413	    timer_lower = sf32lb_timer_initialize(SF32LB_TIMER_DEFAULT_INDEX,
414	                                          1000000);
415	    if (timer_lower == NULL)
416	      {
417	        syslog(LOG_ERR, "ERROR: sf32lb_timer_initialize failed\n");
418	        return -ENODEV;
419	      }
420	
421	    timer_upper = timer_register("/dev/timer0", timer_lower);
422	    if (timer_upper == NULL)
423	      {
424	        ret = -errno;
425	        syslog(LOG_ERR, "ERROR: timer_register(/dev/timer0) failed: %d\n",
426	               errno);
427	        return ret;
428	      }
429	  }
430	#endif
431	#endif
432	
433	#ifdef CONFIG_PWM
434	#if SF32LB_PWM_DEFAULT_INDEX >= 0
435	  {
436	    FAR struct pwm_lowerhalf_s *pwm_lower;
437	
438	    pwm_lower = sf32lb_pwm_initialize(SF32LB_PWM_DEFAULT_INDEX);
439	    if (pwm_lower == NULL)
440	      {
441	        syslog(LOG_ERR, "ERROR: sf32lb_pwm_initialize failed\n");
442	        return -ENODEV;
443	      }
444	
445	    ret = pwm_register("/dev/pwm0", pwm_lower);
446	    if (ret < 0 && ret != -EEXIST)
447	      {
448	        syslog(LOG_ERR, "ERROR: pwm_register(/dev/pwm0) failed: %d\n", ret);
449	        return ret;
450	      }
451	  }
452	#endif
453	#endif
454	
455	#ifdef CONFIG_INPUT_BUTTONS
456	  ret = sf32lb52_button_initialize("/dev/buttons");
457	  if (ret < 0 && ret != -EEXIST)
458	    {
459	      syslog(LOG_ERR, "ERROR: sf32lb52_button_initialize() failed: %d\n",
