513	    {
514	      ret = i2c_register(i2c1, 1);
515	      if (ret < 0)
516	        {
517	          syslog(LOG_ERR, "ERROR: i2c_register(/dev/i2c1) failed: %d\n", ret);
518	        }
519	
520	#if defined(CONFIG_SENSORS_LSM6DSL)
521	      tmpret = sf32lb52_lsm6ds3_initialize(i2c1);
522	      if (tmpret < 0)
523	        {
524	          syslog(LOG_ERR,
525	                 "ERROR: sf32lb52_lsm6ds3_initialize failed: %d\n",
526	                 tmpret);
527	        }
528	#endif
529	    }
530	#endif /* CONFIG_BSP_USING_I2C2 */
531	#endif /* CONFIG_I2C */
532	
533	#if defined(CONFIG_SPI) && defined(CONFIG_BSP_USING_SPI1) && \
534	    defined(CONFIG_SPI_DRIVER)
535	  tmpret = sf32lb52_spi1_register_char();
536	  if (tmpret < 0)
537	    {
538	      serr("WARN: SPI1 char device register failed: %d\n", tmpret);
539	    }
540	#endif
541	
542	#if defined(CONFIG_SPI) && defined(CONFIG_MMCSD_SPI) && \
543	    defined(CONFIG_BSP_USING_SPI1)
544	  tmpret = sf32lb52_tfcard_initialize();
545	  if (tmpret < 0)
546	    {
547	      serr("WARN: TF card init failed: %d\n", tmpret);
548	    }
549	#endif
550	
551	#ifdef CONFIG_LCD
552	  int pid;
553	
554	  pid = task_create("lcd_async_init",
