560	    {
561	      ret = -errno;
562	      syslog(LOG_ERR, "ERROR: lcd_async_init task_create failed: %d\n", ret);
563	      return ret;
564	    }
565	#endif
566	
567	#ifdef CONFIG_WATCHDOG
568	  sf32lb_iwdginitialize("/dev/watchdog0");
569	#endif
570	
571	#ifdef CONFIG_MTD
572	  ret = sf32lb_nor_automount(0,
573	                             SF32LB52_NOR_FS_OFFSET_BLOCKS,
574	                             SF32LB52_NOR_FS_SIZE_BLOCKS);
575	  if (ret < 0)
576	    {
577	      serr("WARN: sf32lb_nor_automount failed: %d\n", ret);
578	    }
579	#endif
580	
581	#ifdef CONFIG_CDCACM
582	  ret = cdcacm_initialize(0, NULL);
583	  if (ret < 0)
584	    {
585	      syslog(LOG_ERR, "ERROR: cdcacm_initialize failed: %d\n", ret);
586	    }
587	#endif
588	
589	#ifdef CONFIG_UART_BTH4
590	  tmpret = sf32lb52_bt_initialize();
591	  if (tmpret < 0 && tmpret != -EEXIST)
592	    {
593	      serr("WARN: sf32lb52_bt_initialize failed: %d\n", tmpret);
