600	/****************************************************************************
601	 * Name: board_early_initialize
602	 *
603	 * Description:
604	 *   If CONFIG_BOARD_EARLY_INITIALIZE is selected, then an additional
605	 *   initialization call will be performed in the boot-up sequence to a
606	 *   function called board_early_initialize().  board_early_initialize()
607	 *   will be called immediately after up_initialize() and well before
608	 *   board_early_initialize() is called and the initial application is
609	 *   started.  The context in which board_early_initialize() executes is
610	 *   suitable for early initialization of most, simple device drivers and
611	 *   is a logical, board-specific extension of up_initialize().
612	 *
613	 *   board_early_initialize() runs on the startup, initialization thread.
614	 *   Some initialization operations cannot be performed on the start-up,
615	 *   initialization thread.  That is because the initialization thread
616	 *   cannot wait for event.  Waiting may be required, for example, to
617	 *   mount a file system or or initialize a device such as an SD card.
618	 *   For this reason, such driver initialize must be deferred to
619	 *   board_late_initialize().
620	
621	 ****************************************************************************/
622	
623	#ifdef CONFIG_BOARD_EARLY_INITIALIZE
624	void board_early_initialize(void)
625	{
626	
627	}
628	#endif
629	
630	/****************************************************************************
631	 * Name: board_late_initialize
632	 *
633	 * Description:
634	 *   If CONFIG_BOARD_LATE_INITIALIZE is selected, then an additional
635	 *   initialization call will be performed in the boot-up sequence to a
636	 *   function called board_late_initialize().  board_late_initialize() will
637	 *   be called after up_initialize() and board_early_initialize() and just
638	 *   before the initial application is started.  This additional
639	 *   initialization phase may be used, for example, to initialize board-
640	 *   specific device drivers for which board_early_initialize() is not
641	 *   suitable.
642	 *
643	 *   Waiting for events, use of I2C, SPI, etc are permissible in the context
644	 *   of board_late_initialize().  That is because board_late_initialize()
645	 *   will run on a temporary, internal kernel thread.
646	 *
647	 ****************************************************************************/
648	
649	#ifdef CONFIG_BOARD_LATE_INITIALIZE
650	void board_late_initialize(void)
651	{
652	  /* Perform board-specific initialization */
653	
654	  sf32lb52_lchspi_ulp_bringup();
655	}
656	#endif
