658	/****************************************************************************
659	 * Name: board_app_initialize
660	 *
661	 * Description:
662	 *   Perform application specific initialization.  This function is never
663	 *   called directly from application code, but only indirectly via the
664	 *   (non-standard) boardctl() interface using the command BOARDIOC_INIT.
665	 *
666	 * Input Parameters:
667	 *   arg - The boardctl() argument is passed to the board_app_initialize()
668	 *         implementation without modification.  The argument has no
669	 *         meaning to NuttX; the meaning of the argument is a contract
670	 *         between the board-specific initialization logic and the
671	 *         matching application logic.  The value could be such things as a
672	 *         mode enumeration value, a set of DIP switch settings, a
673	 *         pointer to configuration data read from a file or serial FLASH,
674	 *         or whatever you would like to do with it.  Every implementation
675	 *         should accept zero/NULL as a default configuration.
676	 *
677	 * Returned Value:
678	 *   Zero (OK) is returned on success; a negated errno value is returned on
679	 *   any failure to indicate the nature of the failure.
680	 *
681	 ****************************************************************************/
682	
683	int board_app_initialize(uintptr_t arg)
684	{
685	#ifdef CONFIG_BOARD_LATE_INITIALIZE
686	  /* Board initialization already performed by board_late_initialize() */
687	
688	  return OK;
689	#else
690	  /* Perform board-specific initialization */
691	
692	  return sf32lb52_lchspi_ulp_bringup();
693	#endif
694	}
