64	    qspi_configure_t qspi_cfg =
65	    {
66	        .Instance = hwp_qspi1,
67	        .SpiMode = BSP_QSPI1_MODE,
68	        .msize = BSP_QSPI1_MEM_SIZE,
69	        .base = QSPI1_MEM_BASE,
70	    };
71	    uint32_t pid = (hwp_hpsys_cfg->IDR & HPSYS_CFG_IDR_PID_Msk) >> HPSYS_CFG_IDR_PID_Pos;
