80	        qspi_cfg.SpiMode = SPI_MODE_LEGPSRAM;    // 32Mb APM LEGACY PSRAM
81	        break;
82	    case 6: //BOOT_PSRAM_WINBOND:                // Winbond HYPERBUS PSRAM
83	        qspi_cfg.SpiMode = SPI_MODE_HBPSRAM;
84	        break;
85	    case 3: // BOOT_PSRAM_APS_64P:
86	    case 2: //BOOT_PSRAM_APS_128P:
87	        qspi_cfg.SpiMode = SPI_MODE_OPSRAM;      // 64Mb APM XCELLA PSRAM
