181	static int SF32LB_FLASH_RAMFUNC sf32lb_flash_preinit_runtime(void)
182	{
183	  FAR FLASH_HandleTypeDef *hflash;
184	  HAL_StatusTypeDef status;
185	  irqstate_t flags;
186	  uint32_t detected_size;
187	
188	  if (g_flash_hw_initialized)
189	    {
190	      return OK;
191	    }
192	
193	  hflash = &g_spi_nor_flash_ctx.handle;
194	
195	  memset(&g_spi_nor_flash_ctx, 0, sizeof(g_spi_nor_flash_ctx));
196	  memset(&g_spi_nor_flash_dma_handle, 0, sizeof(g_spi_nor_flash_dma_handle));
197	
198	  hflash->Instance = FLASH2;
199	  hflash->base = FLASH2_BASE_ADDR;
200	  hflash->size = SF32LB_NOR_TOTAL_SIZE;
201	  hflash->freq = 24000000;
202	
203	  sf32lb_flash_lock();
204	  flags = up_irq_save();
205	  status = HAL_FLASH_PreInit(hflash);
206	  up_irq_restore(flags);
207	  sf32lb_flash_unlock();
208	
209	  if (status != HAL_OK)
210	    {
211	      syslog(LOG_ERR, "ERROR: NOR runtime preinit failed: %d\n", status);
