5	void BSP_GPIO_Set(int pin, int val, int is_porta)
6	{
7	    GPIO_TypeDef *gpio = (is_porta) ? hwp_gpio1 : hwp_gpio2;
8	    GPIO_InitTypeDef GPIO_InitStruct;
9	
10	    // set sensor pin to output mode
11	    GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT;
12	    GPIO_InitStruct.Pin = pin;
13	    GPIO_InitStruct.Pull = GPIO_NOPULL;
14	    HAL_GPIO_Init(gpio, &GPIO_InitStruct);
15	
16	    // set sensor pin to high == power on sensor board
17	    HAL_GPIO_WritePin(gpio, pin, (GPIO_PinState)val);
18	}
